function compute(state) {
  var a = state.a, b = state.b;
  var xs = state.xs.slice();
  var ys = xs.map(function (x) { return a * x + b; });
  var grid = [], line = [];
  for (var x = -5; x <= 5; x += 1) { grid.push(x); line.push(a * x + b); }
  var w = state.w, s = 0;
  for (var i = 0; i < w.length; i++) s += w[i];
  var avg = 0;
  for (var j = 0; j < w.length; j++) avg += (s > 0 ? w[j] / s : 0) * (xs[j] || 0);
  var M = state.M, v = [1, 1];
  var Mv = M.map(function (row) { return row.reduce(function (acc, m, k) { return acc + m * (v[k] || 0); }, 0); });
  var root = a !== 0 ? -b / a : NaN;
  var shown = state.mode === 'abs' ? ys.map(Math.abs) : ys;
  return {
    outputs: { xs: xs, ys: shown, grid: grid, line: line, root: root, avg: avg, M: M, Mv: Mv,
               labels: xs.map(function (x) { return 'x=' + x; }), bw: 40 + 20 * Math.abs(a) },
    intermediates: [
      { label: 'slope a', value: a },
      { label: 'intercept b', value: b },
      { label: 'y values', value: ys },
      { label: 'root x = -b/a', value: root, note: 'undefined when a = 0 (horizontal line)' },
      { label: 'weighted mean of x', value: avg },
      { label: 'M', value: M }
    ],
    checks: [
      { label: 'y(0) equals b', pass: Math.abs((a * 0 + b) - b) < 1e-12, detail: 'y(0) = ' + b },
      { label: 'weights sum to 1', pass: Math.abs(s - 1) < 1e-9, detail: 'sum = ' + s.toFixed(3) }
    ]
  };
}
